func (m *Client) armCircuitTimer(backoff time.Duration) {
	m.timersMu.Lock()
	defer m.timersMu.Unlock()
	if m.isClosing() {
		m.logDropped(workCircuitTest)
		return
	}
	if m.circuitTimer != nil {
		m.circuitTimer.Stop()
	}
	var timer *time.Timer
	// timer is read only under timersMu, where it was written.
	timer = time.AfterFunc(backoff, func() { m.circuitTimerFired(func() bool { return m.circuitTimer == timer }) })
	m.circuitTimer = timer
}

func generateTraceID() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func (m *Client) recordOp(op string) {
	if m.opHook != nil {
		m.opHook(op)
	}
}

func (kv *KVStore) KeysByFilter(ctx context.Context, pattern string) ([]string, error) {
	if ctx == nil {
		return nil, nilContextErrorOf("KVStore", "KeysByFilter")
	}
	ctx, cancel := kv.applyTimeout(ctx)
	defer cancel()

	watcher, constructErr := kv.bucket.WatchFiltered(ctx, []string{pattern}, jetstream.IgnoreDeletes(), jetstream.MetaOnly())
	if watcher == nil {
		if err := ctx.Err(); err != nil {
			return nil, fmt.Errorf("kv keys by filter %q: %w", pattern, err)
		}
		if constructErr == jetstream.ErrNoKeysFound {
			return nil, nil
		}
		if constructErr != nil {
			return nil, fmt.Errorf("kv keys by filter %q: %w", pattern, constructErr)
		}
		return nil, fmt.Errorf("kv keys by filter %q: missing watcher", pattern)
	}

	var keys []string
	primaryErr := constructErr
	if primaryErr == nil {
	collect:
		for {
			// A constructor can return after cancellation while Updates is
			// already readable. Cancellation takes precedence at that boundary.
			if err := ctx.Err(); err != nil {
				primaryErr = err
				break collect
			}
			select {
			case <-ctx.Done():
				primaryErr = ctx.Err()
				break collect
			case entry, ok := <-watcher.Updates():
				if !ok {
					primaryErr = ctx.Err()
					if primaryErr == nil {
						primaryErr = errFilteredWatcherSnapshotIncomplete
					}
					break collect
				}
				if entry == nil {
					primaryErr = ctx.Err()
					break collect
				}
				keys = append(keys, entry.Key())
			}
		}
	}

	// Stop is contextless in the native SDK. Its return is observed before the
	// separate bounded drain begins; neither a goroutine nor a timeout can
	// preempt the Stop call itself.
	stopErr := watcher.Stop()
	terminalCtx, cancelTerminal := context.WithTimeout(context.WithoutCancel(ctx), filteredWatcherDrainTimeout)
	defer cancelTerminal()
	closed := false
	var cleanupErr error
drain:
	for !closed {
		select {
		case _, ok := <-watcher.Updates():
			closed = !ok
		case <-terminalCtx.Done():
			cleanupErr = errFilteredWatcherDeliveryIncomplete
			break drain
		}
	}
	if stopErr != nil && (!closed || (!errors.Is(stopErr, nats.ErrBadSubscription) && !errors.Is(stopErr, nats.ErrConnectionClosed))) {
		cleanupErr = errors.Join(cleanupErr, fmt.Errorf("filtered watcher Stop: %w", stopErr))
	}
	if err := errors.Join(primaryErr, cleanupErr); err != nil {
		return nil, fmt.Errorf("kv keys by filter %q: %w", pattern, err)
	}
	return keys, nil
}

func connStatus(conn *nats.Conn) ConnectionStatus {
	switch {
	case conn.IsConnected():
		return StatusConnected
	case conn.IsReconnecting():
		return StatusReconnecting
	default:
		return StatusDisconnected
	}
}

func (kv *KVStore) UpdateWithRetry(ctx context.Context, key string,
	updateFn func(current []byte) ([]byte, error)) error {
	if ctx == nil {
		return nilContextErrorOf("KVStore", "UpdateWithRetry")
	}
	_, err := kv.UpdateWithRetryRev(ctx, key, updateFn)
	return err
}

func CheckNoLifecycleRetention(name string, maxAge time.Duration, maxBytes int64) error {
	if maxAge > 0 {
		return fmt.Errorf("%w: bucket %q has TTL/MaxAge %s", ErrGraphBucketRetention, name, maxAge)
	}
	if maxBytes > 0 {
		return fmt.Errorf("%w: bucket %q has MaxBytes %d", ErrGraphBucketRetention, name, maxBytes)
	}
	return nil
}

func (kv *KVStore) Put(ctx context.Context, key string, value []byte) (uint64, error) {
	if ctx == nil {
		return 0, nilContextErrorOf("KVStore", "Put")
	}
	ctx, cancel := kv.applyTimeout(ctx)
	defer cancel()

	rev, err := kv.bucket.Put(ctx, key, value)
	if err != nil {
		return 0, fmt.Errorf("kv put %s: %w", key, err)
	}

	if kv.logger != nil {
		kv.logger.Debug("KV put", slog.String("key", key), slog.Uint64("revision", rev))
	}

	return rev, nil
}

func IsNoResponders(err error) bool {
	return errors.Is(err, nats.ErrNoResponders)
}

func (m *Client) Status() ConnectionStatus {
	val := m.status.Load()
	if val == nil {
		return StatusDisconnected
	}
	return val.(ConnectionStatus)
}

func (m *Client) isClosing() bool {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.closing
}

func (kv *KVStore) DeleteAtRevision(ctx context.Context, key string, revision uint64) error {
	if ctx == nil {
		return nilContextErrorOf("KVStore", "DeleteAtRevision")
	}
	if revision == 0 {
		return errs.WrapInvalid(errors.New("revision must be nonzero"), "KVStore", "DeleteAtRevision", "validate revision")
	}
	if err := ValidateKVLiteralKey(key); err != nil {
		return err
	}

	ctx, cancel := kv.applyTimeout(ctx)
	defer cancel()

	if err := kv.bucket.Delete(ctx, key, jetstream.LastRevision(revision)); err != nil {
		if IsKVNotFoundError(err) {
			return ErrKVKeyNotFound
		}
		if IsKVConflictError(err) {
			return ErrKVRevisionMismatch
		}
		return fmt.Errorf("kv delete %s at revision %d: %w", key, revision, err)
	}

	if kv.logger != nil {
		kv.logger.Debug("KV delete at revision", slog.String("key", key), slog.Uint64("revision", revision))
	}

	return nil
}

func (c *Client) RequestReadyClassified(
	ctx context.Context, subject string, data []byte, probeTimeout, budget time.Duration,
) ([]byte, error) {
	msg, err := c.requestMsgReady(ctx, subject, data, probeTimeout, budget)
	if err != nil {
		return nil, err
	}
	return ClassifyReply(msg)
}

func (m *Client) connectFailed() bool {
	m.mu.Lock()
	if m.closing || m.conn != nil {
		m.mu.Unlock()
		return false
	}
	m.commitSeam("connect failure")
	arm, backoff := m.recordFailureLocked()
	if m.Status() != StatusCircuitOpen {
		m.setStatus(StatusDisconnected)
	}
	open := m.Status() == StatusCircuitOpen
	m.mu.Unlock()
	if arm {
		m.armCircuitTimer(backoff)
	}
	return open
}

func (kv *KVStore) Delete(ctx context.Context, key string) error {
	if ctx == nil {
		return nilContextErrorOf("KVStore", "Delete")
	}
	ctx, cancel := kv.applyTimeout(ctx)
	defer cancel()

	err := kv.bucket.Delete(ctx, key)
	if err != nil {
		if IsKVNotFoundError(err) {
			return ErrKVKeyNotFound
		}
		return fmt.Errorf("kv delete %s: %w", key, err)
	}

	if kv.logger != nil {
		kv.logger.Debug("KV delete", slog.String("key", key))
	}

	return nil
}

func (kv *KVStore) Update(ctx context.Context, key string, value []byte, revision uint64) (uint64, error) {
	if ctx == nil {
		return 0, nilContextErrorOf("KVStore", "Update")
	}
	ctx, cancel := kv.applyTimeout(ctx)
	defer cancel()

	rev, err := kv.bucket.Update(ctx, key, value, revision)
	if err != nil {
		if IsKVConflictError(err) {
			return 0, ErrKVRevisionMismatch
		}
		return 0, fmt.Errorf("kv update %s: %w", key, err)
	}

	if kv.logger != nil {
		kv.logger.Debug("KV update", slog.String("key", key), slog.Uint64("old_revision", revision), slog.Uint64("new_revision", rev))
	}

	return rev, nil
}

func (s *Subscription) Unsubscribe() error {
	if s == nil || s.sub == nil {
		return nil
	}
	return s.sub.Unsubscribe()
}

func (c *Client) RequestWithRetryClassified(
	ctx context.Context,
	subject string,
	data []byte,
	timeout time.Duration,
	retry RetryConfig,
) ([]byte, error) {
	msg, err := c.requestMsgWithRetry(ctx, "RequestWithRetryClassified", subject, data, timeout, retry)
	if err != nil {
		return nil, err
	}
	return ClassifyReply(msg)
}

func (m *Client) subscribeWith(
	ctx context.Context, subject string, handler func(context.Context, *nats.Msg), subscribe subscribeFunc,
) (*Subscription, error) {
	return m.subscribeOwned("Subscribe", subject, func(*nats.Conn) nats.MsgHandler {
		return func(msg *nats.Msg) {
			// Create per-message context with timeout
			msgCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
			defer cancel()

			// Extract trace context from message headers
			if tc := ExtractTrace(msg); tc != nil {
				msgCtx = ContextWithTrace(msgCtx, tc)
			}

			handler(msgCtx, msg)
		}
	}, subscribe)
}

func (g *guardedConsumer) CachedInfo() *jetstream.ConsumerInfo {
	g.infoMu.Lock()
	defer g.infoMu.Unlock()
	return g.Consumer.CachedInfo()
}

func (g *guardedConsumer) Info(ctx context.Context) (*jetstream.ConsumerInfo, error) {
	g.infoMu.Lock()
	defer g.infoMu.Unlock()
	return g.Consumer.Info(ctx)
}

func (m *Client) recordStreamPublishFailure(err error) {
	if isCircuitNeutralStreamCapacityError(err) {
		return
	}
	m.recordFailure()
}

func (kv *KVStore) UpdateJSON(ctx context.Context, key string,
	updateFn func(current map[string]any) error) error {
	if ctx == nil {
		return nilContextErrorOf("KVStore", "UpdateJSON")
	}

	return kv.UpdateWithRetry(ctx, key, func(currentBytes []byte) ([]byte, error) {
		// Parse current JSON
		var current map[string]any
		if len(currentBytes) > 0 {
			if err := json.Unmarshal(currentBytes, &current); err != nil {
				// JSON parse error - should not retry as data is corrupt
				return nil, retry.NonRetryable(fmt.Errorf("unmarshal current: %w", err))
			}
		} else {
			current = make(map[string]any)
		}

		// Apply update
		if err := updateFn(current); err != nil {
			return nil, err
		}

		// Marshal back to JSON
		return json.Marshal(current)
	})
}

func WithLogger(logger *slog.Logger) ClientOption {
	return func(c *Client) error {
		if logger == nil {
			logger = slog.Default()
		}
		c.logger = logger
		return nil
	}
}

func WithConnectionLostCallback(fn func(error)) ClientOption {
	return func(c *Client) error {
		c.onConnectionLost = fn
		return nil
	}
}

func ExtractTrace(msg *nats.Msg) *TraceContext {
	if msg == nil || msg.Header == nil {
		return nil
	}

	// Try W3C traceparent first
	if tp := msg.Header.Get(TraceparentHeader); tp != "" {
		tc, err := ParseTraceparent(tp)
		if err == nil {
			return tc
		}
	}

	// Fall back to simplified headers
	traceID := msg.Header.Get(TraceIDHeader)
	if traceID == "" {
		return nil
	}

	return &TraceContext{
		TraceID:      traceID,
		SpanID:       msg.Header.Get(SpanIDHeader),
		ParentSpanID: msg.Header.Get(ParentSpanHeader),
		Sampled:      true,
	}
}

func (m *Client) stopHealthMonitoring() {
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.healthTicker != nil {
		m.healthTicker.Stop()
		m.healthTicker = nil
	}
	if m.healthDone != nil {
		close(m.healthDone)
		m.healthDone = nil
	}
}

func ContextWithTrace(ctx context.Context, tc *TraceContext) context.Context {
	return context.WithValue(ctx, traceContextKey{}, tc)
}

func classForHeader(err error) string {
	switch errs.Classify(err) {
	case errs.ErrorInvalid:
		return ErrorClassInvalid
	case errs.ErrorFatal:
		return ErrorClassFatal
	case errs.ErrorTransient:
		return ErrorClassTransient
	default:
		return ErrorClassTransient
	}
}

func WithConnectionLossTimeout(grace time.Duration) ClientOption {
	return func(c *Client) error {
		c.connectionLossTimeout = grace
		return nil
	}
}

func WithReconnectWait(d time.Duration) ClientOption {
	return func(c *Client) error {
		c.reconnectWait = d
		return nil
	}
}

func IsKVNotFoundError(err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, ErrKVKeyNotFound) {
		return true
	}
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
		return true
	}
	errMsg := err.Error()
	return strings.Contains(errMsg, "key not found") ||
		strings.Contains(errMsg, "key was deleted") ||
		strings.Contains(errMsg, "10037")
}

type TraceContext struct {
	TraceID      string // 32 hex chars (16 bytes)
	SpanID       string // 16 hex chars (8 bytes)
	ParentSpanID string // 16 hex chars, empty for root span
	Sampled      bool
}

func (m *Client) handleClosed(nc *nats.Conn) {
	m.mu.Lock()
	if m.ownsStatusLocked(nc) {
		m.setStatus(StatusDisconnected)
	}
	m.mu.Unlock()
	if nc != nil {
		ch := m.closedSignal(nc)
		m.closedSignalsMu.Lock()
		select {
		case <-ch:
		default:
			close(ch)
		}
		m.closedSignalsMu.Unlock()
	}
}

func (m *Client) ListKeyValueBuckets(ctx context.Context) ([]string, error) {
	if ctx == nil {
		return nil, nilContextError("ListKeyValueBuckets")
	}
	// Check circuit breaker first
	if m.Status() == StatusCircuitOpen {
		return nil, ErrCircuitOpen
	}

	if m.Status() != StatusConnected {
		return nil, ErrNotConnected
	}

	js, err := m.JetStream()
	if err != nil {
		m.recordFailure()
		return nil, err
	}

	// KeyValue stores are implemented as JetStream streams with "KV_" prefix
	names := []string{}
	streamsCh := js.ListStreams(ctx)

	// StreamInfoLister is actually a channel of *StreamInfo
	for stream := range streamsCh.Info() {
		if stream != nil {
			// KV buckets are streams with "KV_" prefix
			if len(stream.Config.Name) > 3 && stream.Config.Name[:3] == "KV_" {
				bucketName := stream.Config.Name[3:] // Remove "KV_" prefix
				names = append(names, bucketName)
			}
		}
	}

	if err := streamsCh.Err(); err != nil {
		m.recordFailure()
		return nil, err
	}

	m.resetCircuit()
	return names, nil
}

func (m *Client) Connect(ctx context.Context) error {
	return m.connectWith(ctx, nats.Connect)
}

func (kv *KVStore) Watch(ctx context.Context, pattern string) (jetstream.KeyWatcher, error) {
	if ctx == nil {
		return nil, nilContextErrorOf("KVStore", "Watch")
	}
	watcher, err := kv.bucket.Watch(ctx, pattern)
	if err != nil {
		return nil, fmt.Errorf("kv watch %s: %w", pattern, err)
	}
	return watcher, nil
}

func (m *Client) connectWith(
	ctx context.Context,
	dial func(string, ...nats.Option) (*nats.Conn, error),
) error {
	if ctx == nil {
		return errs.WrapInvalid(stderrors.New("nil context"), "Client", "Connect", "missing context")
	}
	m.mu.RLock()
	started, closing := m.conn != nil, m.closing
	m.mu.RUnlock()
	if closing {
		return errs.Wrap(nats.ErrConnectionClosed, "Client", "Connect", "client closed")
	}
	if started {
		return errs.WrapInvalid(errs.ErrAlreadyStarted, "Client", "Connect", "already connected")
	}

	// Check circuit breaker first
	if m.Status() == StatusCircuitOpen {
		m.logger.Debug("Circuit breaker is open, skipping connection attempt")
		return ErrCircuitOpen
	}

	// Reported before this call first writes the status, so a test can hold
	// a Connect between its started check and its dial.
	m.recordOp("dial")
	// Connecting is a status commit like any other: written only while no
	// connection is installed and Close has not begun.
	m.mu.Lock()
	if m.closing {
		m.mu.Unlock()
		return errs.Wrap(nats.ErrConnectionClosed, "Client", "Connect", "client closed")
	}
	if m.conn == nil {
		m.setStatus(StatusConnecting)
	}
	m.mu.Unlock()
	m.logger.Info("Connecting to NATS", slog.String("urls", m.urls))

	// Build connection options
	opts := m.buildConnectionOptions()

	conn, err := dial(m.urls, opts...)
	if ctxErr := ctx.Err(); ctxErr != nil {
		m.discardCandidate(conn)
		m.connectFailed()
		return errs.WrapTransient(ctxErr, "Client", "Connect", "connection cancelled")
	}
	if err != nil {
		m.discardCandidate(conn)
		if m.connectFailed() {
			return ErrCircuitOpen
		}
		return errs.WrapTransient(err, "Client", "Connect", "establish connection")
	}

	// Initialize JetStream with new API. The async publish error handler
	// bridges failed async acks into the circuit breaker so a broken ack
	// path opens the breaker exactly as a failed synchronous publish does
	// (see publishToStreamAsync). Keep both candidates local until admission.
	// nats.go v1.54.0 fails jetstream.New only when an option does, and this
	// option never does; the error is still returned, never dropped.
	js, err := jetstream.New(conn, jetstream.WithPublishAsyncErrHandler(m.asyncPublishErrHandler))
	if err != nil {
		m.discardCandidate(conn)
		m.mu.Lock()
		if !m.closing && m.conn == nil {
			m.setStatus(StatusDisconnected)
		}
		m.mu.Unlock()
		return errs.Wrap(err, "Client", "Connect", "initialize JetStream")
	}

	// Admission, under mu: once Close has begun, or another Connect has
	// installed its connection, no connection produced by this dial may become
	// Client state.
	m.mu.Lock()
	if ctxErr := ctx.Err(); ctxErr != nil {
		m.mu.Unlock()
		m.discardCandidate(conn)
		m.connectFailed()
		return errs.WrapTransient(ctxErr, "Client", "Connect", "connection cancelled")
	}
	switch {
	case m.closing:
		m.mu.Unlock()
		m.discardCandidate(conn)
		return errs.Wrap(nats.ErrConnectionClosed, "Client", "Connect", "admit connection")
	case m.conn != nil:
		// A concurrent Connect won admission; its status, failure count and
		// circuit stand, and this candidate's handlers are ignored
		// (ownsStatusLocked) and joined before this call returns.
		m.mu.Unlock()
		m.discardCandidate(conn)
		return errs.WrapInvalid(errs.ErrAlreadyStarted, "Client", "Connect", "already connected")
	}
	m.conn = conn
	m.js = js
	m.dialled = conn
	m.setStatus(StatusConnected)
	m.resetCircuitLocked()
	m.mu.Unlock()

	m.logger.Info("Successfully connected to NATS", slog.String("urls", m.urls))

	// The monitor and the poller start through startBackground, so a Close that
	// has begun since admission refuses them.
	refused := false
	if m.healthInterval > 0 {
		m.logger.Debug("Starting health monitoring", slog.Duration("interval", m.healthInterval))
		refused = !m.startHealthMonitoring()
	}

	if m.jsMetrics != nil && m.metricsInterval > 0 {
		m.logger.Debug("Starting JetStream metrics polling", slog.Duration("interval", m.metricsInterval))
		refused = !m.startMetricsPoller() || refused
	}

	if refused {
		return errs.Wrap(nats.ErrConnectionClosed, "Client", "Connect", "closed while starting")
	}
	return nil
}

func (m *Client) GetStream(ctx context.Context, name string) (jetstream.Stream, error) {
	if ctx == nil {
		return nil, nilContextError("GetStream")
	}
	// Check circuit breaker first
	if m.Status() == StatusCircuitOpen {
		return nil, ErrCircuitOpen
	}

	if m.Status() != StatusConnected {
		return nil, ErrNotConnected
	}

	js, err := m.JetStream()
	if err != nil {
		m.recordFailure()
		return nil, err
	}

	stream, err := js.Stream(ctx, name)
	if err != nil {
		// ErrStreamNotFound is a successful probe result (the stream is absent on
		// this connection right now), not a transport or availability failure.
		// Counting it as a failure would trip the circuit breaker on legitimate
		// existence probes — a component checking whether an optional stream is
		// present, a diagnostic sweep, a caller deciding whether to provision.
		// Only genuine failures (timeout, no-responders, etc.) should move the
		// breaker.
		//
		// The exemption is why this seam is deliberately NOT wired to the
		// consumer setup path's stream-visibility wait: a cheap probe stays
		// cheap. It is also why its answer is not evidence of absence — see the
		// package doc, and ErrStreamNotVisible for the answer that is.
		if !stderrors.Is(err, jetstream.ErrStreamNotFound) {
			m.recordFailure()
			m.jsMetrics.recordError("get_stream")
		}
		return nil, err
	}

	m.resetCircuit()

	// Track stream for metrics collection
	m.jsMetrics.trackStream(name, stream)

	return stream, nil
}

func (m *Client) armConnectionLossTimer(disconnectErr error) {
	if m.connectionLossTimeout <= 0 {
		return
	}

	m.mu.RLock()
	cb := m.onConnectionLost
	m.mu.RUnlock()
	if cb == nil {
		return
	}

	m.timersMu.Lock()
	defer m.timersMu.Unlock()
	if m.isClosing() {
		// Close has begun, so arming is refused: a timer armed now would
		// outlive the join.
		m.logDropped(workConnectionLost)
		return
	}
	if m.lossTimer != nil {
		return
	}
	var timer *time.Timer
	// timer is read only under timersMu, where it was written.
	timer = time.AfterFunc(m.connectionLossTimeout, func() {
		m.connectionLossFired(func() bool { return m.lossTimer == timer }, disconnectErr)
	})
	m.lossTimer = timer
}

func (m *Client) stopTimers() {
	m.timersMu.Lock()
	defer m.timersMu.Unlock()
	if m.lossTimer != nil {
		m.lossTimer.Stop()
		m.lossTimer = nil
	}
	if m.circuitTimer != nil {
		m.circuitTimer.Stop()
		m.circuitTimer = nil
	}
}

func (m *Client) WaitForConnection(ctx context.Context) error {
	if ctx == nil {
		return nilContextError("WaitForConnection")
	}
	ticker := time.NewTicker(10 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return fmt.Errorf("connection timeout: %w", ctx.Err())
		case <-ticker.C:
			if m.IsHealthy() {
				return nil
			}
		}
	}
}

func (m *Client) testCircuit() {
	m.logger.Debug("Testing circuit breaker - attempting to close circuit")

	m.mu.Lock()
	defer m.mu.Unlock()
	if !m.closing && m.Status() == StatusCircuitOpen {
		m.logger.Debug("Circuit breaker test: moving from open to disconnected")
		m.setStatus(StatusDisconnected)
	}
}

func (m *Client) cleanup(
	ctx context.Context,
	conn *nats.Conn,
	drainTimeout time.Duration,
	cancelPoller context.CancelFunc,
	joined chan struct{},
) error {
	m.stopHealthMonitoring()
	m.stopTimers()
	if cancelPoller != nil {
		cancelPoller()
	}

	closeErr := m.drainAndCloseConnection(ctx, conn, drainTimeout)

	awaitHandlers := carriesClientHandlers(conn)
	m.mu.Lock()
	// Only a connection connectWith installed carries the client's handlers;
	// one installed through SetConnection is closed without a handler join.
	if conn != m.dialled {
		awaitHandlers = false
	}
	if m.conn == conn {
		m.conn = nil
	}
	m.js = nil

	// Clear sensitive credentials from memory
	m.username = ""
	m.password = ""

	m.setStatus(StatusDisconnected)
	m.mu.Unlock()

	var handlersOf *nats.Conn
	if awaitHandlers {
		handlersOf = conn
	}
	go m.join(joined, handlersOf)
	return closeErr
}

