func ClassifyReply(msg *nats.Msg) ([]byte, error) {
	if msg == nil {
		return nil, nil
	}

	if msg.Header.Get(HeaderStatus) == HeaderStatusError {
		message, detail := parseErrorBody(msg.Data)
		return nil, classifiedFromHeader(
			msg.Header.Get(HeaderErrorClass),
			msg.Header.Get(HeaderErrorCode),
			message,
			detail,
		)
	}

	return msg.Data, nil
}

func (m *Client) jetStreamWithConn() (jetstream.JetStream, *nats.Conn, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()

	if m.js == nil {
		return nil, nil, errs.WrapTransient(
			fmt.Errorf("JetStream not initialized"),
			"Client", "JetStream", "get JetStream context")
	}

	return m.js, m.dialled, nil
}

func (m *Client) awaitClosedHandler(nc *nats.Conn) {
	<-m.closedSignal(nc)
	m.closedSignalsMu.Lock()
	delete(m.closedSignals, nc)
	m.closedSignalsMu.Unlock()
}

func (m *Client) discardCandidate(conn *nats.Conn) {
	if conn == nil {
		return
	}
	await := carriesClientHandlers(conn)
	conn.Close()
	if await {
		m.awaitClosedHandler(conn)
	}
}

func isHexString(s string) bool {
	for _, c := range s {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
			return false
		}
	}
	return true
}

func (m *Client) startBackground(kind string, fn func()) bool {
	m.mu.Lock()
	if m.closing {
		m.mu.Unlock()
		m.logDropped(kind)
		return false
	}
	finish := m.admitLocked(kind)
	m.mu.Unlock()
	go func() {
		defer finish()
		fn()
	}()
	return true
}

func (kv *KVStore) KeysByPrefix(ctx context.Context, prefix string) ([]string, error) {
	if ctx == nil {
		return nil, nilContextErrorOf("KVStore", "KeysByPrefix")
	}
	// Convert prefix to NATS wildcard pattern
	// "entity.sensor." becomes "entity.sensor.>" to match all keys with that prefix
	return kv.KeysByFilter(ctx, prefix+">")
}

func (m *Client) MaxPayload() (int64, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	if m.conn == nil || !m.conn.IsConnected() {
		return 0, ErrNotConnected
	}
	return m.conn.MaxPayload(), nil
}

func nativeSubscribe(conn *nats.Conn, subject string, cb nats.MsgHandler) (nativeSubscription, error) {
	sub, err := conn.Subscribe(subject, cb)
	if err != nil {
		return nil, err
	}
	return sub, nil
}

func codeForHeader(err error) string {
	var ce *errs.ClassifiedError
	if errors.As(err, &ce) {
		return ce.Code
	}
	return ""
}

func TerminateDelivery(err error) error {
	if err == nil {
		return nil
	}
	return &PermanentDeliveryError{err: err}
}

func (kv *KVStore) UpdateWithRetryRev(ctx context.Context, key string,
	updateFn func(current []byte) ([]byte, error)) (uint64, error) {
	if ctx == nil {
		return 0, nilContextErrorOf("KVStore", "UpdateWithRetryRev")
	}

	// Apply timeout to the entire retry operation
	ctx, cancel := kv.applyTimeout(ctx)
	defer cancel()

	// committedRevision is ASSIGNED (never accumulated) on each successful
	// write, so a CAS retry replaces a losing attempt's value rather than
	// leaving a stale one behind. retry.Do runs the closure synchronously on
	// this goroutine, so the capture needs no synchronization.
	var committedRevision uint64

	// Get retry configuration
	retryConfig := kv.getRetryConfig()

	// Track attempt number for logging
	attemptNum := 0

	// Use the retry package for automatic retry with exponential backoff
	// Note: All errors will be retried except when max attempts is reached.
	// We use consistent error message formatting to indicate error types:
	// - Retryable errors (conflicts): returned as-is to trigger retry
	// - Non-retryable errors: wrapped with context about why they failed
	err := retry.Do(ctx, retryConfig, func() error {
		attemptNum++

		// Get current value with revision
		entry, err := kv.Get(ctx, key)

		var currentValue []byte
		var revision uint64

		if err != nil {
			// Check if key doesn't exist
			if IsKVNotFoundError(err) {
				// Key doesn't exist - treat as empty value with revision 0
				currentValue = nil
				revision = 0
			} else {
				// Network/permission errors - will retry but likely to fail again
				// Wrapped to provide context about the operation that failed
				return fmt.Errorf("kv get failed during update: %w", err)
			}
		} else {
			// Key exists - use its value and revision
			currentValue = entry.Value
			revision = entry.Revision
		}

		// Apply update function to current value
		newValue, err := updateFn(currentValue)
		if err != nil {
			// User logic error - should not retry as it will fail again
			// Wrapped as non-retryable to fail fast
			return retry.NonRetryable(fmt.Errorf("update function error: %w", err))
		}

		// Check value size limit
		if kv.options.MaxValueSize > 0 && len(newValue) > kv.options.MaxValueSize {
			// Validation error - should not retry as it will always fail
			// Wrapped as non-retryable to fail fast
			return retry.NonRetryable(fmt.Errorf("value size validation failed: size %d exceeds maximum %d",
				len(newValue), kv.options.MaxValueSize))
		}

		// Create or update based on whether key exists
		if revision == 0 {
			// Key doesn't exist - create it
			var createdRevision uint64
			createdRevision, err = kv.bucket.Create(ctx, key, newValue)
			if err == nil {
				committedRevision = createdRevision
				return nil // Success!
			}
			// Conflict error - WILL be retried (this is the intended retry case)
			if IsKVConflictError(err) {
				if kv.logger != nil {
					kv.logger.Debug("KV create conflict, retrying",
						slog.String("key", key),
						slog.Int("attempt", attemptNum),
						slog.Int("max_attempts", retryConfig.MaxAttempts),
					)
				}
				// Return conflict error as-is for retry
				return err
			}
			// Infrastructure error - will retry but may not succeed
			// Wrapped to provide context about the operation
			return fmt.Errorf("kv create failed: %w", err)
		}

		// Key exists - update with CAS
		var updatedRevision uint64
		updatedRevision, err = kv.Update(ctx, key, newValue, revision)
		if err == nil {
			committedRevision = updatedRevision
			return nil // Success!
		}
		// Conflict error - WILL be retried (this is the intended retry case)
		if IsKVConflictError(err) {
			if kv.logger != nil {
				kv.logger.Debug("KV update conflict, retrying",
					slog.String("key", key),
					slog.Int("attempt", attemptNum),
					slog.Int("max_attempts", retryConfig.MaxAttempts),
				)
			}
			// Return conflict error as-is for retry
			return err
		}
		// Infrastructure error - will retry but may not succeed
		// Wrapped to provide context about the operation
		return fmt.Errorf("kv update failed: %w", err)
	})

	// Check if we exceeded max retries on a conflict error
	if err != nil && IsKVConflictError(err) {
		return 0, ErrKVMaxRetriesExceeded
	}
	if err != nil {
		return 0, err
	}

	return committedRevision, nil
}

func newSubscription(sub nativeSubscription, onEnd func()) *Subscription {
	s := &Subscription{sub: sub, done: make(chan struct{}), onEnd: onEnd}
	// nats.go calls the closed handler once, after the delivery goroutine
	// exits, on drain, unsubscribe, and connection close alike.
	sub.SetClosedHandler(func(string) { s.closeDone() })
	if !sub.IsValid() {
		// Closed before the handler was set, so it may never fire; doneOnce
		// makes a late fire harmless.
		s.closeDone()
	}
	return s
}

func collectFilteredKeys(ctx context.Context, lister jetstream.KeyLister) ([]string, error) {
	defer func() { _ = lister.Stop() }()

	var keys []string
	for {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case key, ok := <-lister.Keys():
			if !ok {
				if err := ctx.Err(); err != nil {
					return nil, err
				}
				return keys, nil
			}
			keys = append(keys, key)
		}
	}
}

func (m *Client) Close(ctx context.Context) error {
	if ctx == nil {
		return errs.WrapInvalid(stderrors.New("nil context"), "Client", "Close", "missing context")
	}

	// Only the first Close takes the connection and runs the cleanup, bounded
	// by its own context; no lock is held while it drains, so every other
	// Close, and Connect, reaches its own context or refusal at once.
	m.mu.Lock()
	first := !m.closing
	var (
		conn         *nats.Conn
		drainTimeout time.Duration
		cancelPoller context.CancelFunc
	)
	if first {
		m.closing = true
		m.joined = make(chan struct{})
		conn = m.conn
		m.draining = conn
		close(m.closingSignalLocked())
		drainTimeout = m.drainTimeout
		cancelPoller = m.metricsCancel
		m.metricsCancel = nil
	}
	joined := m.joined
	m.mu.Unlock()

	var closeErr error
	if first {
		closeErr = m.cleanup(ctx, conn, drainTimeout, cancelPoller, joined)
	}

	select {
	case <-joined:
		// An ended context is reported even when the join has also finished,
		// so a nil return always means the caller's context was live.
		if err := ctx.Err(); err != nil {
			return err
		}
		if !first {
			return nil
		}
		m.mu.RLock()
		timedOut := m.drainTimedOut
		m.mu.RUnlock()
		if closeErr == nil && timedOut {
			// nats.go gave up the drain and closed the connection itself
			// (nats.go:6349-6390); its report reached handleError before the
			// closed handler the join waited for.
			closeErr = errs.WrapTransient(nats.ErrDrainTimeout, "Client", "Close", "drain timeout")
		}
		return closeErr
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (m *Client) IsHealthy() bool {
	return m.Status() == StatusConnected
}

func (m *Client) Subscribe(ctx context.Context, subject string, handler func(context.Context, *nats.Msg)) (*Subscription, error) {
	// Refused here, not in the callback, which hands ctx to handler for every message.
	if ctx == nil {
		return nil, nilContextError("Subscribe")
	}
	return m.subscribeWith(ctx, subject, handler, nativeSubscribe)
}

type guardedConsumer struct {
	jetstream.Consumer
	infoMu sync.Mutex
	// conn is the connection the consumer's JetStream handle was made on, read with the handle
	// (jetStreamWithConn); nil for a handle that did not come from Connect.
	conn *nats.Conn
}

func isAlreadyExistsError(err error) bool {
	if err == nil {
		return false
	}
	errStr := err.Error()
	return strings.Contains(errStr, "bucket name already in use") ||
		strings.Contains(errStr, "already exists") ||
		strings.Contains(errStr, "stream name already in use")
}

func (m *Client) ownsStatusLocked(nc *nats.Conn) bool {
	return !m.closing && nc == m.conn
}

func (kv *KVStore) Keys(ctx context.Context) ([]string, error) {
	if ctx == nil {
		return nil, nilContextErrorOf("KVStore", "Keys")
	}
	ctx, cancel := kv.applyTimeout(ctx)
	defer cancel()

	keys, err := kv.bucket.Keys(ctx)
	if err != nil {
		// Handle empty bucket case
		if err == jetstream.ErrNoKeysFound {
			return nil, nil
		}
		return nil, fmt.Errorf("kv keys: %w", err)
	}

	return keys, nil
}

func BucketLastSeq(ctx context.Context, bucket interface {
	Status(context.Context) (jetstream.KeyValueStatus, error)
}) (uint64, error) {
	if ctx == nil {
		return 0, nilContextErrorOf("natsclient", "BucketLastSeq")
	}
	status, err := bucket.Status(ctx)
	if err != nil {
		return 0, fmt.Errorf("kv status: %w", err)
	}
	// The concrete JetStream-backed status exposes the backing stream info; the
	// KeyValueStatus interface itself does not surface LastSeq.
	bucketStatus, ok := status.(*jetstream.KeyValueBucketStatus)
	if !ok {
		return 0, fmt.Errorf("kv status: unexpected type %T, want *jetstream.KeyValueBucketStatus", status)
	}
	info := bucketStatus.StreamInfo()
	if info == nil {
		return 0, fmt.Errorf("kv status: nil backing stream info")
	}
	return info.State.LastSeq, nil
}

func (m *Client) setStatus(status ConnectionStatus) {
	m.status.Store(status)
}

func (m *Client) cancelConnectionLossTimer() {
	m.timersMu.Lock()
	defer m.timersMu.Unlock()
	if m.lossTimer != nil {
		m.lossTimer.Stop()
		m.lossTimer = nil
	}
}

func (m *Client) asyncPublishErrHandler(_ jetstream.JetStream, msg *nats.Msg, err error) {
	defer m.admitAlways(workAsyncPublishErr)()
	m.recordStreamPublishFailure(err)
	if m.jsMetrics != nil {
		m.jsMetrics.recordError("publish_async")
	}
	subject := ""
	if msg != nil {
		subject = msg.Subject
	}
	m.logger.Debug("Async publish ack failed",
		slog.String("subject", subject),
		slog.Any("error", err),
	)
}

func (m *Client) admitLocked(kind string) func() {
	m.owned++
	if m.running == nil {
		m.running = make(map[string]int)
	}
	m.running[kind]++
	var once sync.Once
	return func() {
		once.Do(func() {
			m.mu.Lock()
			if m.running[kind]--; m.running[kind] == 0 {
				delete(m.running, kind)
			}
			m.owned--
			if m.owned == 0 && m.idleWait != nil {
				close(m.idleWait)
				m.idleWait = nil
			}
			m.mu.Unlock()
		})
	}
}

func BucketRetention(ctx context.Context, bucket jetstream.KeyValue) (maxAge time.Duration, maxBytes int64, err error) {
	if ctx == nil {
		return 0, 0, nilContextErrorOf("natsclient", "BucketRetention")
	}
	status, err := bucket.Status(ctx)
	if err != nil {
		return 0, 0, fmt.Errorf("kv status: %w", err)
	}
	bucketStatus, ok := status.(*jetstream.KeyValueBucketStatus)
	if !ok {
		return 0, 0, fmt.Errorf("kv status: unexpected type %T, want *jetstream.KeyValueBucketStatus", status)
	}
	info := bucketStatus.StreamInfo()
	if info == nil {
		return 0, 0, fmt.Errorf("kv status: nil backing stream info")
	}
	return info.Config.MaxAge, info.Config.MaxBytes, nil
}

